mapper.insert:
	/* 안전교육 등록 */
    INSERT INTO content (
        title, content_type, visible_yn, body, content_link, 
        ordering, user_id, created_at, last_update_date
    ) VALUES (
        #{title}, #{contentType}, #{visibleYn}, #{body}, #{contentLink}, 
        #{ordering}, #{userId}, NOW(), NOW()
    )

mapper.delete:
	/* 안전교육 다건 삭제 */
    DELETE FROM content WHERE content_id IN

        #{id}

mapper.update:
	/* 공개, 비공개 수정 */
    UPDATE content
    SET visible_yn = #{visibleYn}, last_update_date = NOW()
    WHERE content_id IN

        #{id}
